def fewest_coins(coins, amount):
    inf = float("inf")
    best = [0] + [inf] * amount
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value and best[value - coin] + 1 < best[value]:
                best[value] = best[value - coin] + 1
    return best[amount] if best[amount] != inf else -1

def lcs_length(a, b):
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                table[i][j] = max(table[i - 1][j], table[i][j - 1])
    return table[len(a)][len(b)]

def solve(n):
    solutions = []
    placed = []
    cols, diag1, diag2 = set(), set(), set()

    def place(row):
        if row == n:
            solutions.append(list(placed))
            return
        for col in range(n):
            if col in cols or row - col in diag1 or row + col in diag2:
                continue
            cols.add(col); diag1.add(row - col); diag2.add(row + col); placed.append(col)
            place(row + 1)
            cols.remove(col); diag1.remove(row - col); diag2.remove(row + col); placed.pop()

    place(0)
    return solutions

def find_all(text, pattern):
    failure = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k and pattern[i] != pattern[k]:
            k = failure[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        failure[i] = k
    matches = []
    k = 0
    for i, char in enumerate(text):
        while k and char != pattern[k]:
            k = failure[k - 1]
        if char == pattern[k]:
            k += 1
        if k == len(pattern):
            matches.append(i - k + 1)
            k = failure[k - 1]
    return matches

def build_order(needs):
    state = {}
    order = []

    def visit(task):
        if state.get(task) == "done":
            return
        if state.get(task) == "active":
            raise ValueError(f"cycle at {task}")
        state[task] = "active"
        for dependency in needs.get(task, []):
            visit(dependency)
        state[task] = "done"
        order.append(task)

    for task in needs:
        visit(task)
    return order

